"use client";

// ─── Word Ladder ─────────────────────────────────────────────────────────────
// You are given a start word and a target word. Change ONE letter at a time,
// each step has to be a real word, and you are done when you reach the target.
//
//   COLD → CORD → WORD
//
// A round is five ladders, short ones first. "Today's ladders" are the same five
// for every player on a given day, so people can compare; "Random" deals a fresh
// five. Words and puzzles come from ./data (generated by tools/ladder/gen.py).
//
// How you play: tap the letter you want to change, then tap its replacement on
// the keyboard. Letters already in the right place for the target turn green.
//
// Nothing here talks to the backend yet: scores are kept on the device. A round
// is a list of words, which a server can replay and check exactly, so this game
// is a good fit for a ranked board later.

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { PUZZLES, VALID } from "./data";

const DISPLAY = '"Melon Pop", "Fredoka", ui-sans-serif, system-ui, sans-serif';
const ROUND = 5;
const PARS = [2, 3, 3, 4, 4]; // short first, so the first ladder teaches the game
const KEYS = ["qwertyuiop", "asdfghjkl", "zxcvbnm"];
const BEST_KEY = "gamearena:ladder:best";

const WORDS = new Set(VALID.split(" "));

// small seeded generator so "today" is the same five ladders for everyone
function rng(seed: number) { let a = seed >>> 0; return () => { a = (a + 0x6d2b79f5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
function dayNumber() { const d = new Date(); return Math.floor(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) / 86400000); }
function deal(seed: number): [string, string, number][] {
  const r = rng(seed); const used = new Set<string>();
  return PARS.map((par) => {
    const pool = PUZZLES.filter((p) => p[2] === par && !used.has(p[0]) && !used.has(p[1]));
    const p = pool[Math.floor(r() * pool.length)]; used.add(p[0]); used.add(p[1]);
    return p;
  });
}

// one good next word from `from` toward `to` (shortest route through accepted words)
function nextStep(from: string, to: string): string | null {
  if (from === to) return null;
  const prev = new Map<string, string>([[to, ""]]); const q = [to];
  for (let h = 0; h < q.length; h++) {
    const w = q[h];
    for (let i = 0; i < 4; i++) for (let c = 97; c < 123; c++) {
      const x = w.slice(0, i) + String.fromCharCode(c) + w.slice(i + 1);
      if (x === w || prev.has(x) || !WORDS.has(x)) continue;
      prev.set(x, w); if (x === from) return w; q.push(x);
    }
  }
  return null;
}

interface Result { start: string; target: string; par: number; steps: number; seconds: number; hints: number; skipped: boolean; points: number }
function pointsFor(par: number, steps: number, seconds: number, hints: number) {
  const route = steps <= par ? 50 : Math.max(0, 50 - (steps - par) * 10);
  const speed = Math.max(0, 50 - Math.floor(seconds / 2));
  return Math.max(20, 100 + route + speed - hints * 30);
}

export default function WordLadderPage() {
  const router = useRouter();
  const [phase, setPhase] = useState<"start" | "play" | "done">("start");
  const [daily, setDaily] = useState(true);
  const [set, setSet] = useState<[string, string, number][]>([]);
  const [ix, setIx] = useState(0);
  const [rungs, setRungs] = useState<string[]>([]);
  const [sel, setSel] = useState(0);
  const [msg, setMsg] = useState<{ text: string; key: number } | null>(null);
  const [shake, setShake] = useState(0);
  const [hints, setHints] = useState(0);
  const [hintWord, setHintWord] = useState<string | null>(null);
  const [solved, setSolved] = useState(false);
  const [results, setResults] = useState<Result[]>([]);
  const [secs, setSecs] = useState(0);
  const [best, setBest] = useState(0);
  const t0 = useRef(0);
  const ladderEnd = useRef<HTMLDivElement>(null);

  useEffect(() => { try { setBest(Number(localStorage.getItem(BEST_KEY) || 0)); } catch { /* private window */ } }, []);

  const puzzle = set[ix];
  const start = puzzle?.[0] ?? ""; const target = puzzle?.[1] ?? ""; const par = puzzle?.[2] ?? 0;
  const current = rungs.length ? rungs[rungs.length - 1] : start;

  const openPuzzle = useCallback((list: [string, string, number][], i: number) => {
    const [s, t] = list[i];
    setIx(i); setRungs([]); setHints(0); setHintWord(null); setSolved(false); setMsg(null);
    setSel(Math.max(0, [0, 1, 2, 3].findIndex((k) => s[k] !== t[k])));
    t0.current = Date.now(); setSecs(0);
  }, []);
  const begin = (isDaily: boolean) => {
    const list = deal(isDaily ? dayNumber() : Math.floor(Math.random() * 2 ** 31));
    setDaily(isDaily); setSet(list); setResults([]); setPhase("play"); openPuzzle(list, 0);
  };

  useEffect(() => {
    if (phase !== "play" || solved) return;
    const t = setInterval(() => setSecs(Math.floor((Date.now() - t0.current) / 1000)), 500);
    return () => clearInterval(t);
  }, [phase, solved, ix]);
  useEffect(() => { ladderEnd.current?.scrollIntoView({ block: "nearest", behavior: "smooth" }); }, [rungs.length]);

  const say = (text: string) => setMsg({ text, key: Date.now() });
  const finishPuzzle = (steps: number, skipped: boolean) => {
    const seconds = Math.floor((Date.now() - t0.current) / 1000);
    const r: Result = { start, target, par, steps, seconds, hints, skipped, points: skipped ? 0 : pointsFor(par, steps, seconds, hints) };
    const all = [...results, r]; setResults(all); setSolved(true);
    setTimeout(() => {
      if (ix + 1 < ROUND) openPuzzle(set, ix + 1);
      else {
        const total = all.reduce((a, x) => a + x.points, 0);
        if (total > best) { setBest(total); try { localStorage.setItem(BEST_KEY, String(total)); } catch { /* ignore */ } }
        setPhase("done");
      }
    }, skipped ? 500 : 1300);
  };

  const type = useCallback((letter: string) => {
    if (phase !== "play" || solved || !puzzle) return;
    if (current[sel] === letter) return;
    const next = current.slice(0, sel) + letter + current.slice(sel + 1);
    if (!WORDS.has(next)) { setShake((n) => n + 1); say(`${next.toUpperCase()} is not a word`); try { navigator.vibrate?.(40); } catch { /* no haptics */ } return; }
    if (next === start || rungs.includes(next)) { setShake((n) => n + 1); say("You already used that word"); return; }
    const list = [...rungs, next]; setRungs(list); setHintWord(null); setMsg(null);
    if (next === target) { finishPuzzle(list.length, false); return; }
    const nxt = [0, 1, 2, 3].findIndex((k) => next[k] !== target[k]);
    if (next[sel] === target[sel] && nxt >= 0) setSel(nxt);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [phase, solved, puzzle, current, sel, rungs, start, target]);
  const undo = () => { if (!solved && rungs.length) { setRungs(rungs.slice(0, -1)); setHintWord(null); setMsg(null); } };
  const hint = () => {
    if (solved) return;
    const w = nextStep(current, target);
    if (!w) { say("No route from here. Undo a step"); return; }
    setHints((h) => h + 1); setHintWord(w); setSel([0, 1, 2, 3].findIndex((k) => w[k] !== current[k]));
  };

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (phase !== "play") return;
      if (e.key === "ArrowLeft") setSel((s) => (s + 3) % 4);
      else if (e.key === "ArrowRight") setSel((s) => (s + 1) % 4);
      else if (e.key === "Backspace") undo();
      else if (/^[a-zA-Z]$/.test(e.key) && !e.metaKey && !e.ctrlKey && !e.altKey) type(e.key.toLowerCase());
    };
    window.addEventListener("keydown", onKey); return () => window.removeEventListener("keydown", onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [phase, type, rungs, solved]);

  const total = useMemo(() => results.reduce((a, x) => a + x.points, 0), [results]);
  const share = async () => {
    const lines = results.map((r) => (r.skipped ? "⬜" : r.steps <= r.par ? "🟩" : "🟨")).join("");
    const text = `Word Ladder on GameArena\n${lines}  ${total} pts\nhttps://gamearenahq.xyz/games/ladder`;
    try { if (navigator.share) await navigator.share({ text }); else { await navigator.clipboard.writeText(text); say("Copied"); } } catch { /* cancelled */ }
  };

  const Tiles = ({ word, kind, onTap }: { word: string; kind: "start" | "target" | "rung" | "live"; onTap?: (i: number) => void }) => (
    <div className={`wl-row ${kind}`}>
      {word.split("").map((ch, i) => (
        <button key={i} disabled={!onTap} onClick={() => onTap?.(i)}
          className={`wl-tile${kind !== "target" && ch === target[i] ? " hit" : ""}${kind === "live" && i === sel ? " sel" : ""}${hintWord && kind === "live" && hintWord[i] !== ch ? " nudge" : ""}`}
          aria-label={kind === "live" ? `Letter ${i + 1}: ${ch}${i === sel ? ", selected" : ""}` : undefined}>
          {ch}
        </button>
      ))}
    </div>
  );

  return (
    <div className="wl">
      <header className="wl-top">
        <button className="wl-back" onClick={() => (phase === "play" ? setPhase("start") : router.push("/dashboard"))} aria-label="Back">←</button>
        <b style={{ fontFamily: DISPLAY }}>Word Ladder</b>
        {phase === "play" ? <span className="wl-meta">{ix + 1} / {ROUND}</span> : <span className="wl-meta" />}
      </header>

      {phase === "start" && (
        <main className="wl-start">
          <h1 style={{ fontFamily: DISPLAY }}>Turn one word<br />into another</h1>
          <p>Change <b>one letter</b> at a time. Every step has to be a real word.</p>
          <div className="wl-demo" aria-hidden>
            {["cold", "cord", "word"].map((w, r) => (
              <div key={w} className="wl-row demo" style={{ animationDelay: `${r * 0.5}s` }}>
                {w.split("").map((ch, i) => <span key={i} className={`wl-tile${ch === "word"[i] ? " hit" : ""}`}>{ch}</span>)}
              </div>
            ))}
          </div>
          <button className="wl-primary" style={{ fontFamily: DISPLAY }} onClick={() => begin(true)}>Play today&apos;s ladders</button>
          <button className="wl-ghost" onClick={() => begin(false)}>Random ladders</button>
          <div className="wl-small">Five ladders a round. Today&apos;s five are the same for everyone.{best > 0 ? ` Your best: ${best}.` : ""}</div>
        </main>
      )}

      {phase === "play" && puzzle && (
        <main className="wl-play">
          <div className="wl-goal">
            <span>TARGET</span>
            <Tiles word={target} kind="target" />
            <span className="wl-par">{rungs.length} step{rungs.length === 1 ? "" : "s"} · par {par} · {secs}s</span>
          </div>

          <div className="wl-ladder">
            <Tiles word={start} kind={rungs.length ? "start" : "live"} onTap={rungs.length || solved ? undefined : setSel} />
            {rungs.map((w, i) => {
              const live = i === rungs.length - 1;
              return <div key={`${w}${i}`} className={live && !solved ? `wl-shake-${shake % 2}` : ""}><Tiles word={w} kind={live ? "live" : "rung"} onTap={live && !solved ? setSel : undefined} /></div>;
            })}
            {solved && <div className="wl-solved" style={{ fontFamily: DISPLAY }}>{results[results.length - 1]?.skipped ? "Skipped" : rungs.length <= par ? "Perfect route!" : "Solved!"}{!results[results.length - 1]?.skipped && <i>+{results[results.length - 1]?.points}</i>}</div>}
            <div ref={ladderEnd} />
          </div>

          <div className="wl-msg" key={msg?.key ?? "none"} role="status">{hintWord ? `Try ${hintWord.toUpperCase()}` : msg?.text ?? (rungs.length === 0 ? "Tap a letter above, then tap its replacement" : "")}</div>

          <div className="wl-tools">
            <button onClick={undo} disabled={!rungs.length || solved}>Undo</button>
            <button onClick={hint} disabled={solved}>Hint −30</button>
            <button onClick={() => !solved && finishPuzzle(rungs.length, true)} disabled={solved}>Skip</button>
          </div>

          <div className="wl-keys">
            {KEYS.map((row) => (
              <div key={row}>{row.split("").map((k) => <button key={k} onClick={() => type(k)} className={hintWord && hintWord[sel] === k ? "glow" : ""}>{k}</button>)}</div>
            ))}
          </div>
        </main>
      )}

      {phase === "done" && (
        <main className="wl-done">
          <div className="wl-kicker">{daily ? "TODAY'S LADDERS" : "RANDOM LADDERS"}</div>
          <h1 style={{ fontFamily: DISPLAY }}>{total} <small>points</small></h1>
          {total >= best && total > 0 && <div className="wl-new">New best</div>}
          <ul>
            {results.map((r, i) => (
              <li key={i}>
                <b>{r.start.toUpperCase()} → {r.target.toUpperCase()}</b>
                <span>{r.skipped ? "skipped" : `${r.steps} step${r.steps === 1 ? "" : "s"} (par ${r.par}) · ${r.seconds}s`}</span>
                <i className={r.skipped ? "" : r.steps <= r.par ? "g" : "y"}>{r.points}</i>
              </li>
            ))}
          </ul>
          <button className="wl-primary" style={{ fontFamily: DISPLAY }} onClick={() => begin(false)}>Play again</button>
          <div className="wl-pair"><button className="wl-ghost" onClick={share}>Share</button><button className="wl-ghost" onClick={() => router.push("/dashboard")}>Home</button></div>
          {msg && <div className="wl-msg" key={msg.key}>{msg.text}</div>}
        </main>
      )}

      <style>{`
        .wl { min-height: 100dvh; display: flex; flex-direction: column; background: linear-gradient(180deg, #f3eeff 0%, #e6dcff 100%); color: #22104f; font-family: ui-sans-serif, system-ui, -apple-system, sans-serif; --brand: #6d28d9; --line: rgba(76,29,149,0.16); --dim: rgba(34,16,79,0.62); }
        .wl button { font: inherit; color: inherit; cursor: pointer; -webkit-tap-highlight-color: transparent; }
        .wl-top { display: grid; grid-template-columns: 44px 1fr 44px; align-items: center; padding: 10px 14px; text-align: center; }
        .wl-top b { font-size: 20px; font-weight: 400; }
        .wl-back { width: 40px; height: 40px; border-radius: 14px; border: 1px solid var(--line); background: #fff; font-size: 18px; }
        .wl-meta { font-size: 13px; font-weight: 800; color: var(--dim); text-align: right; }
        .wl main { flex: 1; width: 100%; max-width: 460px; margin: 0 auto; padding: 4px 16px 18px; display: flex; flex-direction: column; }

        .wl-row { display: flex; justify-content: center; gap: 7px; }
        .wl-tile { width: 54px; height: 54px; display: grid; place-items: center; border-radius: 14px; border: 2px solid var(--line); background: #fff; font-size: 26px; font-weight: 800; text-transform: uppercase; color: #22104f; padding: 0; transition: transform .14s cubic-bezier(.2,.9,.3,1.4), background .2s ease, border-color .2s ease, color .2s ease; }
        .wl-tile:disabled { cursor: default; }
        .wl-tile.hit { background: #16a34a; border-color: #15803d; color: #fff; }
        .wl-row.start .wl-tile, .wl-row.rung .wl-tile { width: 44px; height: 44px; font-size: 20px; border-radius: 12px; opacity: 0.78; }
        .wl-row.target .wl-tile { background: transparent; border-style: dashed; border-color: rgba(109,40,217,0.5); color: var(--brand); }
        .wl-row.live .wl-tile { box-shadow: 0 5px 0 rgba(76,29,149,0.18); }
        .wl-row.live .wl-tile.sel { border-color: var(--brand); transform: translateY(-5px); box-shadow: 0 10px 0 rgba(109,40,217,0.28); }
        .wl-row.live .wl-tile.sel:not(.hit) { background: #f1e9ff; }
        .wl-row.live .wl-tile.nudge { animation: wlNudge .7s ease-in-out infinite; }
        @keyframes wlNudge { 50% { transform: translateY(-8px); } }

        .wl-start { text-align: center; justify-content: center; gap: 14px; }
        .wl-start h1 { margin: 0; font-size: clamp(30px, 8.5vw, 42px); line-height: 1.05; font-weight: 400; }
        .wl-start p { margin: 0; font-size: 15.5px; line-height: 1.45; color: var(--dim); }
        .wl-start p b { color: #22104f; }
        .wl-demo { display: flex; flex-direction: column; gap: 7px; margin: 8px 0 10px; }
        .wl-row.demo { animation: wlDrop .5s cubic-bezier(.2,.8,.2,1) both; }
        .wl-row.demo .wl-tile { width: 48px; height: 48px; font-size: 22px; }
        @keyframes wlDrop { from { opacity: 0; transform: translateY(-14px); } to { opacity: 1; transform: none; } }
        .wl-primary { width: 100%; padding: 16px 0; border: none; border-radius: 18px; font-size: 20px; color: #fff !important; background: var(--brand); box-shadow: 0 6px 0 #4c1d95, 0 18px 30px -14px rgba(109,40,217,0.9); transition: transform .12s ease, box-shadow .12s ease; }
        .wl-primary:active { transform: translateY(4px); box-shadow: 0 2px 0 #4c1d95; }
        .wl-ghost { width: 100%; padding: 13px 0; border-radius: 16px; border: 1px solid var(--line); background: #fff; font-size: 15px; font-weight: 800; }
        .wl-small { font-size: 12.5px; color: var(--dim); line-height: 1.4; }

        .wl-play { gap: 10px; }
        .wl-goal { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 10px; border-radius: 20px; background: rgba(255,255,255,0.6); border: 1px solid var(--line); }
        .wl-goal > span:first-child { font-size: 10.5px; font-weight: 900; letter-spacing: 0.2em; color: var(--brand); }
        .wl-goal .wl-tile { width: 46px; height: 46px; font-size: 22px; }
        .wl-par { font-size: 12px; font-weight: 700; color: var(--dim); font-variant-numeric: tabular-nums; }
        .wl-ladder { flex: 1; min-height: 120px; display: flex; flex-direction: column; align-items: center; justify-content: flex-end; gap: 7px; overflow-y: auto; padding: 8px 0 6px; scrollbar-width: none; }
        .wl-ladder::-webkit-scrollbar { display: none; }
        .wl-ladder > div > .wl-row.live, .wl-ladder > .wl-row.live { animation: wlRung .32s cubic-bezier(.2,.9,.3,1.3) both; }
        @keyframes wlRung { from { opacity: 0; transform: translateY(-12px) scale(0.94); } to { opacity: 1; transform: none; } }
        .wl-shake-0 { animation: wlShakeA .3s; } .wl-shake-1 { animation: wlShakeB .3s; }
        @keyframes wlShakeA { 25% { transform: translateX(-7px); } 75% { transform: translateX(7px); } }
        @keyframes wlShakeB { 25% { transform: translateX(7px); } 75% { transform: translateX(-7px); } }
        .wl-solved { display: flex; align-items: baseline; gap: 10px; font-size: 24px; color: #15803d; animation: wlPop .5s cubic-bezier(.2,.9,.3,1.5) both; }
        .wl-solved i { font-style: normal; font-size: 18px; color: var(--brand); }
        @keyframes wlPop { from { opacity: 0; transform: scale(0.6); } to { opacity: 1; transform: none; } }
        .wl-msg { min-height: 20px; text-align: center; font-size: 13.5px; font-weight: 700; color: var(--dim); animation: wlFade .25s ease both; }
        @keyframes wlFade { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
        .wl-tools { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
        .wl-tools button { padding: 10px 0; border-radius: 12px; border: 1px solid var(--line); background: #fff; font-size: 13px; font-weight: 800; }
        .wl-tools button:disabled { opacity: 0.4; cursor: default; }
        .wl-keys { display: flex; flex-direction: column; gap: 6px; padding-bottom: env(safe-area-inset-bottom, 0px); }
        .wl-keys > div { display: flex; justify-content: center; gap: 5px; }
        .wl-keys button { flex: 1 1 0; max-width: 40px; height: 48px; border-radius: 10px; border: none; background: #fff; box-shadow: 0 3px 0 rgba(76,29,149,0.2); font-size: 17px; font-weight: 800; text-transform: uppercase; padding: 0; transition: transform .08s ease, background .15s ease; }
        .wl-keys button:active { transform: translateY(3px); box-shadow: none; background: #e9defe; }
        .wl-keys button.glow { background: var(--brand); color: #fff; }

        .wl-done { text-align: center; justify-content: center; gap: 12px; }
        .wl-kicker { font-size: 11px; font-weight: 900; letter-spacing: 0.2em; color: var(--brand); }
        .wl-done h1 { margin: 0; font-size: 64px; line-height: 1; font-weight: 400; }
        .wl-done h1 small { font-size: 18px; color: var(--dim); }
        .wl-new { align-self: center; padding: 5px 14px; border-radius: 999px; background: #16a34a; color: #fff; font-size: 12px; font-weight: 900; letter-spacing: 0.08em; }
        .wl-done ul { list-style: none; margin: 4px 0 6px; padding: 0; display: flex; flex-direction: column; gap: 6px; text-align: left; }
        .wl-done li { display: grid; grid-template-columns: 1fr auto; column-gap: 10px; padding: 10px 14px; border-radius: 14px; background: #fff; border: 1px solid var(--line); }
        .wl-done li b { font-size: 14.5px; letter-spacing: 0.04em; }
        .wl-done li span { grid-column: 1; font-size: 12px; color: var(--dim); font-weight: 600; }
        .wl-done li i { grid-row: 1 / span 2; grid-column: 2; align-self: center; font-style: normal; font-size: 18px; font-weight: 900; color: var(--dim); }
        .wl-done li i.g { color: #15803d; } .wl-done li i.y { color: #b45309; }
        .wl-pair { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }

        @media (max-height: 690px) { .wl-tile { width: 46px; height: 46px; font-size: 22px; } .wl-goal .wl-tile { width: 38px; height: 38px; font-size: 18px; } .wl-row.start .wl-tile, .wl-row.rung .wl-tile { width: 36px; height: 36px; font-size: 16px; } .wl-keys button { height: 42px; } .wl-goal { padding: 7px; } }
        @media (prefers-reduced-motion: reduce) { .wl * { animation: none !important; transition: none !important; } }
      `}</style>
    </div>
  );
}
